/// <summary>
/// This is a task class to support bundling multithreading.
/// </summary>
class METDutyAdValorumClaimGenerateJob
{
    RecordInsertList recordInsertList;
    boolean          dutyBySite;
    boolean          generateClaim;
    boolean          filterItemSite;
    container        conItems;
    NumberSeq        numberSeqClaimLine,
                     numberSeqClaimInvoice;

}

Method.Source:
/// <summary>
/// Main processing method
/// </summary>
/// <param name = "_contract">METDutyAdValorumClaimGenerateContract class object</param>
public void process(METDutyAdValorumClaimGenerateContract _contract)
{
    #OCCRetryCount

    try
    {
        ttsbegin;

        METDutyAdValorumClaimTmp dutyAdValorumClaimTmp;

        dutyBySite       = _contract.parmDutyValuesBySite();
        generateClaim    = _contract.parmGenerateClaims();
        filterItemSite   = _contract.parmFilterItemSite();
        conItems         = _contract.parmConItems();
        recordInsertList = new RecordInsertList(tableNum(METExciseSiteDutySetup));

        if (generateClaim)
        {
            this.getClaimLineIdNumberSeq();
            this.getClaimInvoiceNumberSeq();
        }

        for (int i = 1; i <= conLen(conItems); i++)
        {
            dutyAdValorumClaimTmp = conpeek(conItems, i);

            this.processItems(dutyAdValorumClaimTmp.Site, dutyAdValorumClaimTmp.ItemId);
        }

        recordInsertList.insertDatabase();

        ttscommit;

    }
    catch(Exception::Deadlock)
    {
        retry;
    }
    catch (Exception::UpdateConflict)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::UpdateConflictNotRecovered;
            }
            else
            {
                retry;
            }
        }
        else
        {
            throw Exception::UpdateConflict;
        }

    }

}

/// <summary>
/// Processes items.
/// </summary>
/// <param name = "_siteId">Site Id.</param>
/// <param name = "_itemId">Item Id.</param>
private void processItems(InventSiteId _siteId, ItemId _itemId)
{
    METDutyRollVariance     dutyRollVariance;
    METInventTable          metInventTable;
    METTariffItemCode       tariffItemCode;


    if (dutyBySite)
    {
        METExciseSiteDutySetup  exciseSiteDutySetup;
        METDutyRollValuesLine dutyRollValuesLine;
        utcdatetime currentDateTime = DateTimeUtil::utcNow();

        select firstonly forupdate validtimestate(currentDateTime) AverageVFD, TotalDutyPerCase, ExcisePerCase, ValidFrom from dutyRollValuesLine
            where dutyRollValuesLine.Site == _siteId
                && dutyRollValuesLine.ItemId == _itemId;

        if (dutyRollValuesLine.RecId)
        {
            metInventTable = metInventTable::find(_itemId);
            exciseSiteDutySetup = METExciseSiteDutySetup::find(dutyRollValuesLine.Site, dutyRollValuesLine.ItemId);

            exciseSiteDutySetup.ValueForDuty    = dutyRollValuesLine.AverageVFD;
            tariffItemCode  = METTariffItemCode::findRecId(metInventTable.METTariffItemCodeBaseRecid);
            //Duty amount = (pack size * Bottlesize * (AlcStrn/100) * Duty-LAL) + (VFD * (Adval Rate/100))

            exciseSiteDutySetup.DutyTotal       = dutyRollValuesLine.TotalDutyPerCase;
            exciseSiteDutySetup.CalcDate        = DateTimeUtil::getSystemDate(DateTimeUtil::getCompanyTimeZone());
            exciseSiteDutySetup.RunBy           = curUserId();
            exciseSiteDutySetup.ValidFrom       = DateTimeUtil::date(dutyRollValuesLine.ValidFrom);
            exciseSiteDutySetup.ExcisePerCase   = dutyRollValuesLine.ExcisePerCase;

            if (exciseSiteDutySetup.RecId)
            {
                ttsbegin;
                exciseSiteDutySetup.selectForUpdate(true);
                exciseSiteDutySetup.update();
                ttscommit;
            }
            else
            {
                exciseSiteDutySetup.ItemId  = _itemId;
                exciseSiteDutySetup.SiteId  = _siteId;
                recordInsertList.add(exciseSiteDutySetup);
            }
        }
    }

    if (generateClaim)
    {
        while select dutyRollVariance
            order by CreatedDateTime
                where dutyRollVariance.ItemId == _itemId
                    && dutyRollVariance.Site == _siteId
                    && dutyRollVariance.ClaimCreated == NoYes::No
                    && dutyRollVariance.InventTransType == InventTransType::Purch
                    && dutyRollVariance.ClaimAmount != 0
                    && dutyRollVariance.IsAccrualPosted

        {
            METVendorClaimTable vendorClaimTable;

            ttsbegin;
            dutyRollVariance.selectForUpdate(true);
            dutyRollVariance.ClaimCreated = NoYes::Yes;
            dutyRollVariance.update();

            vendorClaimTable = this.initVendorClaimFromDutyRollVariance(dutyRollVariance);

            vendorClaimTable.insert();
            ttscommit;
        }
    }
}

/// <summary>
/// init from DutyRollVariance
/// </summary>
/// <param name = "_dutyRollVariance">DutyRollVariance.</param>
/// <returns>METVendorClaimTable</returns>
private METVendorClaimTable initVendorClaimFromDutyRollVariance(METDutyRollVariance _dutyRollVariance)
{
    METVendorClaimTable     vendorClaimTable;

    vendorClaimTable.clear();
    vendorClaimTable.ClaimLineId        = numberSeqClaimLine.num();
    vendorClaimTable.ClaimType          = MetVendClaimType::VFDVariance;
    vendorClaimTable.SiteId             = _dutyRollVariance.Site;
    vendorClaimTable.ItemId             = _dutyRollVariance.ItemId;
    vendorClaimTable.modifiedField(fieldNum(METVendorClaimTable, ItemId));
    vendorClaimTable.ClaimAmount        = decRound(_dutyRollVariance.ClaimAmount, 2);
    vendorClaimTable.VendAccount        = _dutyRollVariance.VendAccount;
    vendorClaimTable.ClaimDate          = DateTimeUtil::getSystemDate(DateTimeUtil::getCompanyTimeZone());
    METExciseSiteDutySetup exciseSiteDutySetup = METExciseSiteDutySetup::find(_dutyRollVariance.Site, _dutyRollVariance.ItemId);
    vendorClaimTable.VFDCurrent         = exciseSiteDutySetup.ValueForDuty;
    vendorClaimTable.VFDReceived        = _dutyRollVariance.DutyValue;
    vendorClaimTable.ClaimInvoiceId     = numberSeqClaimInvoice.num();
    vendorClaimTable.DutyRollVariance   = _dutyRollVariance.RecId;

    return vendorClaimTable;
}

// <summary>
/// Number sequence for Vendor claim lineId
/// </summary>
private void getClaimLineIdNumberSeq()
{
    NumberSequenceReference numberSequenceReference;
    NumberSequenceTable     numberSequenceTable;

    numberSequenceReference = GUPParameters::numRefMETVendClaimLineId();
    numberSequenceTable = NumberSequenceTable::find(numberSequenceReference.NumberSequenceId);

    if (numberSequenceTable)
    {
        numberSeqClaimLine = NumberSeq::newGetNum(numberSequenceReference);
    }

}

/// <summary>
/// Get the claim invoice number sequence
/// </summary>
private void getClaimInvoiceNumberSeq()
{
    numberSeqClaimInvoice =  NumberSeq::newGetNumFromId(METExciseDutyParameteres::find().ExciseClaimNumberSequence);
}
